using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class C02RefineFeeds {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var lab=root.Find("C01_Experiment_Art");var origin=new Vector3(-17.23132775f,-82,-1.074689f);var rot=Quaternion.LookRotation(new Vector3(-.242535625f,0,.9701425f));var output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_C02_Refine/"));var players=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToArray();var was=players.Select(r=>r.enabled).ToArray();foreach(var r in players)r.enabled=false;
 var shots=new[]{new{n=1,p=lab.position+new Vector3(-.5f,6.8f,6.8f),t=lab.position+new Vector3(-.3f,0,1.2f),f=85f},new{n=2,p=lab.position+new Vector3(3.6f,1.65f,3.5f),t=lab.position+new Vector3(8.7f,.45f,.85f),f=80f},new{n=3,p=lab.position+new Vector3(.9f,1.65f,4.2f),t=lab.position+new Vector3(-1.7f,.25f,7.8f),f=80f},new{n=4,p=origin+rot*new Vector3(.10f,1.65f,1.40f),t=origin+rot*new Vector3(0,1.45f,13.8f),f=76f}};
 try{foreach(var shot in shots){var g=new GameObject("Temporary_Current_CameraFeed");var cam=g.AddComponent<Camera>();cam.transform.position=shot.p;cam.transform.LookAt(shot.t);cam.fieldOfView=shot.f;cam.nearClipPlane=.035f;cam.farClipPlane=200;cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(output+"Feed_"+shot.n.ToString("00")+".png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}finally{for(int i=0;i<players.Length;i++)players[i].enabled=was[i];EditorSceneManager.OpenScene(s.path);}return new{feeds=4,currentScene=s.path};}
}
